package msfasp

import (
	"github.com/TheManticoreProject/Manticore/network/dcerpc/ndr"
)

// FW_CRYPTO_SET ([MS-FASP]). Generated by tools/idlgen; verify pointer/array tags.
type FW_CRYPTO_SET struct {
	PNext              *FW_CRYPTO_SET `ndr:"unique"`
	WSchemaVersion     uint16
	IpSecPhase         FW_IPSEC_PHASE
	WszSetId           *ndr.WSTR `ndr:"unique"`
	WszName            *ndr.WSTR `ndr:"unique"`
	WszDescription     *ndr.WSTR `ndr:"unique"`
	WszEmbeddedContext *ndr.WSTR `ndr:"unique"`
	Field              FW_CRYPTO_SET_Field
	Origin             FW_RULE_ORIGIN_TYPE
	WszGPOName         *ndr.WSTR `ndr:"unique"`
	Status             FW_RULE_STATUS
	DwCryptoSetFlags   ndr.DWORD
}

// FW_CRYPTO_SET_Field is the IpSecPhase-discriminated union of FW_CRYPTO_SET
// ([MS-FASP] 2.2.75): FW_IPSEC_PHASE_1 (1) carries the Phase 1 suites; FW_IPSEC_PHASE_2
// (2) carries the Phase 2 suites. The inline discriminant is transmitted per [C706] 14.3.8.
type FW_CRYPTO_SET_Field struct {
	Tag    FW_IPSEC_PHASE       `ndr:"switch,enum"`
	Phase1 FW_CRYPTO_SET_PHASE1 `ndr:"case=1"`
	Phase2 FW_CRYPTO_SET_PHASE2 `ndr:"case=2"`
}

// FW_CRYPTO_SET_PHASE1 is the Phase 1 arm of FW_CRYPTO_SET_Field ([MS-FASP] 2.2.75).
type FW_CRYPTO_SET_PHASE1 struct {
	WFlags            uint16
	DwNumPhase1Suites ndr.DWORD
	PPhase1Suites     []FW_PHASE1_CRYPTO_SUITE `ndr:"unique,size_is=DwNumPhase1Suites"`
	DwTimeOutMinutes  ndr.DWORD
	DwTimeOutSessions ndr.DWORD
}

// FW_CRYPTO_SET_PHASE2 is the Phase 2 arm of FW_CRYPTO_SET_Field ([MS-FASP] 2.2.75).
type FW_CRYPTO_SET_PHASE2 struct {
	Pfs               FW_PHASE2_CRYPTO_PFS
	DwNumPhase2Suites ndr.DWORD
	PPhase2Suites     []FW_PHASE2_CRYPTO_SUITE `ndr:"unique,size_is=DwNumPhase2Suites"`
}
